681: int bsd_udp_packet_buffer_ecn(void *msgvec, int index) {
682: 
683: #if defined(_WIN32) || defined(__APPLE__)
684:     printf("ECN not supported!\n");
685: #else
686:     // we should iterate all control messages once, after recvmmsg and then only fetch them with these functions
687:     struct msghdr *mh = &((struct mmsghdr *) msgvec)[index].msg_hdr;
688:     for (struct cmsghdr *cmsg = CMSG_FIRSTHDR(mh); cmsg != NULL; cmsg = CMSG_NXTHDR(mh, cmsg)) {
689:         // do we need to get TOS from ipv6 also?
690:         if (cmsg->cmsg_level == IPPROTO_IP) {
691:             if (cmsg->cmsg_type == IP_TOS) {
692:                 uint8_t tos = *(uint8_t *)CMSG_DATA(cmsg);
693:                 return tos & 3;
694:             }
695:         }
696: 
697:         if (cmsg->cmsg_level == IPPROTO_IPV6) {
