332: 
333:     struct us_internal_ssl_socket_context_t *context = (struct us_internal_ssl_socket_context_t *) us_socket_context(0, &s->s);
334: 
335:     // todo: cork here so that we efficiently output both from reading and from writing?
336: 
337:     if (s->ssl_read_wants_write) {
338:         s->ssl_read_wants_write = 0;
